:25px 13px 60px}.top{padding:23px;align-items:flex-start;flex-direction:column}.top>div:last-child{justify-content:flex-start}.grid{grid-template-columns:1fr}.login{margin:18px auto;padding:23px}.login h1,.top h1{font-size:29px}.card{padding:19px}.msg small{float:none;display:block;margin-top:3px}}
</style></head><body><main class="wrap"><?php if(!$member){?><section class="card login"><h1>Alumni Community</h1><p>Private access for approved AYISEC alumni.</p><?php if($error){?><p class="error"><?php echo alumni_safe($error);?></p><?php }?><form method="post"><label>Email or phone</label><input name="identity" required><label>Password</label><input type="password" name="password" required><button name="alumni_login">Sign in</button> <a class="btn" href="alumni-join.php">Register</a> <a class="btn" href="alumni-claim.php">Claim existing profile</a> <a class="btn" href="alumni.php">Alumni page</a></form></section><?php }else{$room=($_GET['room']??'general')==='year-'.$member['graduationyear']?'year-'.$member['graduationyear']:'general';$directory=mysqli_query($con,"SELECT alumniid,fullname,graduationyear,programme,locationtext,occupation,profileimage,photoconsent FROM tblalumni WHERE status='active' AND directoryconsent=1 ORDER BY graduationyear DESC,fullname ASC LIMIT 100");$messages=mysqli_query($con,"SELECT c.*,a.fullname FROM tblalumnichatmessage c JOIN tblalumni a ON a.alumniid=c.alumniid WHERE c.chatroom='".mysqli_real_escape_string($con,$room)."' ORDER BY c.createdat DESC LIMIT 60");?><div class="top"><div><h1>Welcome, <?php echo alumni_safe($member['fullname']);?></h1><p>Verified AYISEC alumni only.</p></div><div><a class="btn" href="alumni-profile.php">My profile</a> <a class="btn" href="alumni.php">Public alumni page</a> <a class="btn" href="?logout=1">Sign out</a></div></div><div class="grid"><section class="card"><h2>Alumni directory</h2><?php while($directory&&($person=mysqli_fetch_assoc($directory))){?><div class="person"><?php if($person['photoconsent']&&$person['profileimage']){?><img class="avatar" src="alumni-photo.php?id=<?php echo rawurlencode($person['alumniid']);?>" alt=""><?php }else{?><span class="avatar"></span><?php }?><div><b><?php echo alumni_safe($person['fullname']);?></b><br><small><?php echo alumni_safe($person['graduationyear'].' · '.$person['programme']);?><br><?php echo alumni_safe($person['occupation'].' · '.$person['locationtext']);?></small></div></div><?php }?></section><section class="card"><h2>Alumni conversations</h2><p><a href="?room=general">General community</a> · <a href="?room=year-<?php echo (int)$member['graduationyear'];?>">Class of <?php echo (int)$member['graduationyear'];?></a></p><?php if($member['chatconsent']){?><form method="post"><input type="hidden" name="csrf" value="<?php echo alumni_safe(alumni_csrf_token());?>"><input type="hidden" name="room" value="<?php echo $room==='general'?'general':'year';?>"><textarea name="messagebody" maxlength="1000" placeholder="Share an update with your alumni community" required></textarea><button name="send_message">Post message</button></form><?php }else{?><p>You did not consent to chat when registering.</p><?php }?><div><?php while($messages&&($message=mysqli_fetch_assoc($messages))){?><article class="msg"><strong><?php echo alumni_safe($message['fullname']);?></strong><small><?php echo alumni_safe(date('d M, g:i a',strtotime($message['createdat'])));?></small><p><?php echo nl2br(alumni_safe($message['messagebody']));?></p></article><?php }?></div></section></div><?php }?></main><?php include('alumni-help-widget.php'); ?></body></html>
